"""Write the bot names behind `isBot` and the four category functions into every place they live.

	python3 .github/scripts/bots/generate.py          # rewrite the files
	python3 .github/scripts/bots/generate.py --check  # only report the files that are out of date

`bots.json`, next to this script, is the only file to edit. From it this script writes the
pattern module of each package, the `bots.json` fixture each package's tests read, and the
name tables and counts in the reference pages of both documentation locales. The three
packages must agree, which is why none of those files is edited by hand.

Before writing anything, every example is checked against every category: an example has to
be claimed by its own category and by no other one, a name in `other` by none of the four,
and every User-Agent under `userAgents.human` by nothing at all. Python's `re` does the
checking; the tests of each package then repeat it with that package's own engine.

Python 3.8 or later, and nothing outside the standard library.
"""

import argparse
import json
import re
import sys
import textwrap
import unicodedata
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
SOURCE = HERE / 'bots.json'

CATEGORIES = ('search', 'aiSearch', 'aiAgent', 'aiTraining')
GROUPS = CATEGORIES + ('other',)
FUNCTIONS = {
	'search': 'isSearchBot',
	'aiSearch': 'isAiSearchBot',
	'aiAgent': 'isAiAgentBot',
	'aiTraining': 'isAiTrainingBot',
}
CONSTANTS = {
	'search': 'SEARCH_BOTS',
	'aiSearch': 'AI_SEARCH_BOTS',
	'aiAgent': 'AI_AGENT_BOTS',
	'aiTraining': 'AI_TRAINING_BOTS',
	'other': 'OTHER_BOTS',
}
DART_NAMES = {
	'search': 'searchBots',
	'aiSearch': 'aiSearchBots',
	'aiAgent': 'aiAgentBots',
	'aiTraining': 'aiTrainingBots',
	'other': 'otherBots',
}
COMMENTS = {
	'search': 'Crawlers that index pages for a search engine.',
	'aiSearch': 'Crawlers that index pages so an AI product can cite them, and that their operator says do not train models.',
	'aiAgent': 'Fetchers that visit a page only when a person asks an AI assistant or agent to, and the robots.txt names of such fetchers.',
	'aiTraining': 'Crawlers that collect pages to train AI models or to build datasets for that, and the robots.txt names that control such use.',
	'other': 'Bots in none of the four categories: SEO tools, link previews, monitors, feed readers, archivers, HTTP libraries and the like. A name that a generic word already matches is left out of the code.',
	'generic': 'Words that only an automated client puts in its name. `isBot` reads them; the four categories do not.',
	'notBot': 'Devices and apps whose names contain one of those words. They are taken out of the string before the words are read.',
}
MIT_NOTICE = """Copyright (c) 2024 ai.robots.txt
Copyright (c) 2017 Martin Monperrus

Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE."""
HEADER = """{intro}

Each entry is the source of a regular expression, matched without case anywhere in the string, and the three packages carry the same lists in the same order. A name is filed where its operator's own documentation puts it first. Where the operator says nothing, the verified bot directory of Cloudflare Radar decides.

Generated by `.github/scripts/bots/generate.py` from `.github/scripts/bots/bots.json`. Edit the source and run the script rather than editing this file.

The AI names cover every name in the ai.robots.txt project, and many of the other names come from the crawler-user-agents project. Both are published under the MIT License:

""" + MIT_NOTICE
INTROS = {
	'js': '(Private, not exported from the package) The names behind `isBot`, `isSearchBot`, `isAiSearchBot`, `isAiAgentBot` and `isAiTrainingBot`.',
	'dart': '(Private, not exported from the package) The names behind [isBot], [isSearchBot], [isAiSearchBot], [isAiAgentBot] and [isAiTrainingBot].',
	'python': '(Private) The names behind `isBot`, `isSearchBot`, `isAiSearchBot`, `isAiAgentBot` and `isAiTrainingBot`.',
}
MONTHS = (
	'January', 'February', 'March', 'April', 'May', 'June',
	'July', 'August', 'September', 'October', 'November', 'December',
)

# Characters that make a pattern more than a plain name once its escaped characters are gone.
REGEXP_SYNTAX = re.compile(r'[\\^$.*+?()\[\]{}|]')
ESCAPED_CHARACTER = re.compile(r'\\(\W)')


def default_match(name):
	return re.sub(r'([.^$*+?()\[\]{}|\\])', r'\\\1', name.lower())


def match_of(entry):
	return entry.get('match', default_match(entry['name']))


def example_of(entry):
	return entry.get('example', entry['name'])


def entries(source, group):
	return [entry for operator in source[group] for entry in operator['names']]


def is_plain(pattern):
	return not REGEXP_SYNTAX.search(ESCAPED_CHARACTER.sub('', pattern))


def plain_text(pattern):
	return ESCAPED_CHARACTER.sub(r'\1', pattern)


def compile_all(patterns):
	return re.compile('|'.join(patterns), re.IGNORECASE | re.ASCII)


def validate(source):
	errors = []

	for group in GROUPS:
		for entry in entries(source, group):
			pattern = match_of(entry)

			if '(?<' in pattern:
				errors.append(f'{entry["name"]}: lookbehind is not allowed, an older Safari cannot parse it')

			try:
				re.compile(pattern)
			except re.error as error:
				errors.append(f'{entry["name"]}: {error}')

	if errors:
		return errors

	patterns = {group: compile_all(match_of(entry) for entry in entries(source, group)) for group in GROUPS}
	generic = compile_all(word['match'] for word in source['genericWords'])
	not_bot = compile_all(word['match'] for word in source['notBot'])

	def is_bot(text):
		stripped = not_bot.sub('', text)
		return any(patterns[group].search(stripped) for group in GROUPS) or bool(generic.search(stripped))

	def check(group, text):
		for category in CATEGORIES:
			claimed = bool(patterns[category].search(text))

			if claimed != (category == group):
				errors.append(f'{group}: {text!r} is {"" if claimed else "not "}claimed by {category}')

		if is_bot(text) != (group != 'human'):
			errors.append(f'{group}: {text!r} is {"" if group == "human" else "not "}a bot to isBot')

	for group in GROUPS:
		for entry in entries(source, group):
			check(group, example_of(entry))

	for group, user_agents in source['userAgents'].items():
		for user_agent in user_agents:
			check(group, user_agent)

	return errors


def code_patterns(source, group):
	"""The patterns written into the code, without those another one already covers."""
	patterns = [match_of(entry) for entry in entries(source, group)]
	plain = [plain_text(pattern) for pattern in patterns if is_plain(pattern)]
	generic = compile_all(word['match'] for word in source['genericWords'])
	kept = []

	for pattern in patterns:
		if is_plain(pattern):
			text = plain_text(pattern)

			# A shorter plain name in the same list already matches wherever this one does.
			if any(other != text and other in text for other in plain):
				continue

			# The same goes for a generic word, which `isBot` reads along with `other`.
			if group == 'other' and generic.search(text):
				continue

		kept.append(pattern)

	return kept


def operators(source, group, quote, indent, comment):
	lines = []
	kept = set(code_patterns(source, group))

	for operator in source[group]:
		patterns = [match_of(entry) for entry in operator['names'] if match_of(entry) in kept]

		if not patterns:
			continue

		lines.append(f'{indent}{comment} {operator["operator"]}')
		lines.extend(f'{indent}{quote(pattern)},' for pattern in patterns)

	return lines


def wrap(text, width):
	lines = []

	for paragraph in text.split('\n\n'):
		for line in paragraph.split('\n'):
			lines.extend(textwrap.wrap(line, width) or [''])

		lines.append('')

	return lines[:-1]


def js_string(pattern):
	return "'" + pattern.replace('\\', '\\\\').replace("'", "\\'") + "'"


def raw_string(pattern):
	if "'" in pattern:
		raise ValueError(f'a pattern cannot contain a single quote: {pattern}')

	return "r'" + pattern + "'"


def javascript(source):
	out = ['/*!']
	out.extend(f' * {line}'.rstrip() for line in wrap(HEADER.format(intro=INTROS['js']), 88))
	out.append(' */')

	def array(constant, items, comment):
		lines = ['']
		lines.extend(f'// {line}' for line in textwrap.wrap(comment, 92))
		lines.append(f'const {constant}: string[] = [')
		lines.extend(items)
		lines[-1] = lines[-1].rstrip(',')
		lines.append('];')
		return lines

	for group in GROUPS:
		out.extend(array(CONSTANTS[group], operators(source, group, js_string, '\t', '//'), COMMENTS[group]))

	out.extend(array('GENERIC_BOT_WORDS', [f'\t{js_string(word["match"])},' for word in source['genericWords']], COMMENTS['generic']))
	out.append('')
	out.extend(f'// {line}' for line in textwrap.wrap(COMMENTS['notBot'], 92))
	out.append(f"export const NOT_BOT_PATTERN = new RegExp({js_string('|'.join(word['match'] for word in source['notBot']))}, 'gi');")
	out.append('')

	for group in CATEGORIES:
		out.append(f"export const {CONSTANTS[group].replace('_BOTS', '_BOT_PATTERN')} = new RegExp({CONSTANTS[group]}.join('|'), 'i');")

	out.append('export const BOT_PATTERN = new RegExp(')
	out.append('\t[')
	out.extend(f'\t\t...{name},' for name in [CONSTANTS[group] for group in GROUPS] + ['GENERIC_BOT_WORDS'])
	out[-1] = out[-1].rstrip(',')
	out.append("\t].join('|'),")
	out.append("\t'i'")
	out.append(');')
	return '\n'.join(out) + '\n'


DART_HELPER = r"""
/// (Private) Dart's regular expressions try every alternative at every position of the
/// string, which made several hundred names cost a few hundred microseconds for an
/// ordinary browser string. The plain names are folded into a trie instead, so a position
/// that cannot start any of them is given up after a character or two.
final RegExp _escapedCharacter = RegExp(r'\\(\W)');
final RegExp _regExpSyntax = RegExp(r'[\\^$.*+?()[\]{}|]');

RegExp _compileNames(List<String> names) {
  final Map<String, dynamic> trie = {};
  final List<String> others = [];

  for (final String name in names) {
    if (_regExpSyntax.hasMatch(name.replaceAll(_escapedCharacter, ''))) {
      others.add(name);
      continue;
    }

    Map<String, dynamic> node = trie;

    for (final String character in name
        .replaceAllMapped(_escapedCharacter, (Match m) => m[1]!)
        .split('')) {
      node = node.putIfAbsent(character, () => <String, dynamic>{});
    }

    node[''] = true;
  }

  return RegExp([if (trie.isNotEmpty) _trieSource(trie), ...others].join('|'),
      caseSensitive: false);
}

String _trieSource(Map<String, dynamic> node) {
  // A shorter name already ends here, which is all a search needs.
  if (node.containsKey('')) {
    return '';
  }

  final List<String> branches = [
    for (final MapEntry<String, dynamic> entry in node.entries)
      RegExp.escape(entry.key) + _trieSource(entry.value),
  ];

  return branches.length == 1 ? branches.first : '(?:${branches.join('|')})';
}
"""


def dart(source):
	out = [f'/// {line}'.rstrip() for line in wrap(HEADER.format(intro=INTROS['dart']), 88)]
	out.append('library;')

	def list_(name, items, comment):
		lines = ['']
		lines.extend(f'/// {line}' for line in textwrap.wrap(comment, 80))
		lines.append(f'const List<String> {name} = [')
		lines.extend(items)
		lines.append('];')
		return lines

	for group in GROUPS:
		out.extend(list_(DART_NAMES[group], operators(source, group, raw_string, '  ', '//'), COMMENTS[group]))

	out.extend(list_('genericBotWords', [f'  {raw_string(word["match"])},' for word in source['genericWords']], COMMENTS['generic']))
	out.append('')
	out.extend(f'/// {line}' for line in textwrap.wrap(COMMENTS['notBot'], 80))
	out.append(f"final RegExp notBotPattern = RegExp({raw_string('|'.join(word['match'] for word in source['notBot']))}, caseSensitive: false);")
	out.append(DART_HELPER)

	for group in CATEGORIES:
		out.append(f'final RegExp {DART_NAMES[group]}Pattern = _compileNames({DART_NAMES[group]});')

	out.append('final RegExp botPattern = _compileNames([')
	out.extend(f'  ...{name},' for name in [DART_NAMES[group] for group in GROUPS] + ['genericBotWords'])
	out.append(']);')
	return '\n'.join(out) + '\n'


PYTHON_HELPER = r"""
# `re` tries every alternative at every position of the string, which made several hundred
# names cost more than half a millisecond for an ordinary browser string. The plain names are
# folded into a trie instead, so a position that cannot start any of them is given up after a
# character or two. `re.ASCII` keeps `\b` and case folding to ASCII, as in JavaScript and Dart.
_ESCAPED_CHARACTER = re.compile(r'\\(\W)')
_REGEXP_SYNTAX = re.compile(r'[\\^$.*+?()[\]{}|]')


def _trieSource(node: dict) -> str:
	# A shorter name already ends here, which is all a search needs.
	if '' in node:
		return ''

	branches = [re.escape(character) + _trieSource(child) for character, child in node.items()]

	return branches[0] if len(branches) == 1 else '(?:' + '|'.join(branches) + ')'


def _compileNames(names: tuple) -> 're.Pattern[str]':
	trie: dict = {}
	others = []

	for name in names:
		if _REGEXP_SYNTAX.search(_ESCAPED_CHARACTER.sub('', name)):
			others.append(name)
			continue

		node = trie

		for character in _ESCAPED_CHARACTER.sub(r'\1', name):
			node = node.setdefault(character, {})

		node[''] = {}

	return re.compile('|'.join(([_trieSource(trie)] if trie else []) + others), re.IGNORECASE | re.ASCII)
"""


def python(source):
	out = ['"""' + '\n'.join(wrap(HEADER.format(intro=INTROS['python']), 88)).rstrip(), '"""', '', 'import re']

	def tuple_(name, items, comment):
		lines = ['']
		lines.extend(f'# {line}' for line in textwrap.wrap(comment, 90))
		lines.append(f'{name} = (')
		lines.extend(items)
		lines.append(')')
		return lines

	for group in GROUPS:
		out.extend(tuple_(f'_{CONSTANTS[group]}', operators(source, group, raw_string, '\t', '#'), COMMENTS[group]))

	out.extend(tuple_('_GENERIC_BOT_WORDS', [f'\t{raw_string(word["match"])},' for word in source['genericWords']], COMMENTS['generic']))
	out.append('')
	out.extend(f'# {line}' for line in textwrap.wrap(COMMENTS['notBot'], 90))
	out.append(f"_NOT_BOT_PATTERN = re.compile({raw_string('|'.join(word['match'] for word in source['notBot']))}, re.IGNORECASE | re.ASCII)")
	out.append(PYTHON_HELPER)

	for group in CATEGORIES:
		out.append(f"_{CONSTANTS[group].replace('_BOTS', '_BOT_PATTERN')} = _compileNames(_{CONSTANTS[group]})")

	out.append('_BOT_PATTERN = _compileNames(')
	out.append('\t' + ' + '.join(f'_{CONSTANTS[group]}' for group in GROUPS) + ' + _GENERIC_BOT_WORDS')
	out.append(')')
	return '\n'.join(out) + '\n'


def fixture(source):
	"""Every example and every User-Agent, by the group the tests expect it in."""
	groups = {}

	for group in GROUPS + ('human',):
		values = [example_of(entry) for entry in entries(source, group)] if group != 'human' else []
		values += source['userAgents'].get(group, [])
		groups[group] = list(dict.fromkeys(values))

	return json.dumps(groups, ensure_ascii=False, indent='\t') + '\n'


def month(source, locale):
	year, number = (int(part) for part in source['updated'].split('-'))

	return f'{MONTHS[number - 1]} {year}' if locale == 'en' else f'{year}년 {number}월'


# Prettier lines a table's columns up only while the result fits in this many columns, the
# `max_line_length` of `.editorconfig`, and leaves a wider table unpadded.
TABLE_WIDTH = 100


def display_width(text):
	return sum(2 if unicodedata.east_asian_width(character) in ('W', 'F') else 1 for character in text)


def name_table(source, group, locale):
	rows = [('Operator', 'Names') if locale == 'en' else ('운영사', '이름')]

	for operator in sorted(source[group], key=lambda operator: (operator['operator'] == 'Unknown', operator['operator'].lower())):
		name = operator['operator']

		if locale == 'ko' and name == 'Unknown':
			name = '확인되지 않음'

		rows.append((name, ', '.join(entry['name'] for entry in operator['names'])))

	widths = [max(3, *(display_width(row[column]) for row in rows)) for column in range(2)]

	if 2 + widths[0] + 3 + widths[1] + 2 > TABLE_WIDTH:
		lines = [f'| {left} | {right} |' for left, right in rows]
		lines.insert(1, '| --- | --- |')
	else:
		def pad(text, width):
			return text + ' ' * (width - display_width(text))

		lines = [f'| {pad(left, widths[0])} | {pad(right, widths[1])} |' for left, right in rows]
		lines.insert(1, f'| {"-" * widths[0]} | {"-" * widths[1]} |')

	return '\n'.join(lines)


def names_section(source, group, locale):
	count = len(entries(source, group))

	if locale == 'en':
		intro = f'## Recognized names\n\nThe {count:,} names below are matched as of {month(source, locale)}, grouped by the company or project that runs them. Names the operator documents itself are listed together with names found only in public bot directories.'
	else:
		intro = f'## 알아보는 이름\n\n{month(source, locale)} 기준으로 아래 {count:,}개 이름을 알아보며, 운영하는 회사나 프로젝트별로 묶었습니다. 운영사가 직접 밝힌 이름과 공개된 봇 목록에서만 확인한 이름이 함께 있습니다.'

	return f'{intro}\n\n{name_table(source, group, locale)}\n'


def counts_sentence(source, locale):
	n = {group: len(entries(source, group)) for group in GROUPS}
	total = sum(n.values())

	if locale == 'en':
		return f"`isBot` knows {total:,} names as of {month(source, locale)}, besides the generic words: {n['search']:,} search crawlers, {n['aiSearch']:,} AI search crawlers, {n['aiAgent']:,} AI agents, {n['aiTraining']:,} AI training crawlers and {n['other']:,} other bots. Each category function's page lists its names."

	return f"{month(source, locale)} 기준으로 `isBot`은 일반 단어 외에 이름 {total:,}개를 알아봅니다. 검색 크롤러 {n['search']:,}개, AI 검색 크롤러 {n['aiSearch']:,}개, AI 에이전트 {n['aiAgent']:,}개, AI 학습 크롤러 {n['aiTraining']:,}개, 기타 봇 {n['other']:,}개이며, 분류별 이름은 각 분류 함수 페이지에 있습니다."


HEADINGS = {'en': '## Recognized names', 'ko': '## 알아보는 이름'}
COUNTS = {
	'en': re.compile(r'^`isBot` knows .*$', re.MULTILINE),
	'ko': re.compile(r'^\d{4}년 \d{1,2}월 기준으로 `isBot`은 .*$', re.MULTILINE),
}


def documentation(source):
	"""The reference pages with their generated parts replaced."""
	pages = {}

	for locale in ('en', 'ko'):
		directory = ROOT / 'docs' / 'src' / locale / 'reference' / 'web'

		for group, function in FUNCTIONS.items():
			path = directory / f'{function}.md'
			text = path.read_text(encoding='utf-8')
			start = text.find(HEADINGS[locale])

			if start < 0:
				raise SystemExit(f'{path}: the heading "{HEADINGS[locale]}" is missing')

			pages[path] = text[:start] + names_section(source, group, locale)

		path = directory / 'isBot.md'
		text = path.read_text(encoding='utf-8')

		if not COUNTS[locale].search(text):
			raise SystemExit(f'{path}: the paragraph with the counts is missing')

		pages[path] = COUNTS[locale].sub(lambda _: counts_sentence(source, locale), text)

	return pages


def main():
	parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
	parser.add_argument('--check', action='store_true', help='report the files that are out of date and write nothing')
	arguments = parser.parse_args()

	source = json.loads(SOURCE.read_text(encoding='utf-8'))
	errors = validate(source)

	if errors:
		print('\n'.join(errors), file=sys.stderr)
		return 1

	files = {
		ROOT / 'packages/javascript/lib/web/_botPatterns.ts': javascript(source),
		ROOT / 'packages/dart/lib/src/web/_bots.dart': dart(source),
		ROOT / 'packages/python/qsu/web/_bots.py': python(source),
	}
	text = fixture(source)

	for path in ('packages/javascript/test/_resources/bots.json', 'packages/dart/test/_resources/bots.json', 'packages/python/tests/_resources/bots.json'):
		files[ROOT / path] = text

	files.update(documentation(source))
	stale = [path for path, content in files.items() if not path.exists() or path.read_text(encoding='utf-8') != content]

	if arguments.check:
		for path in stale:
			print(f'out of date: {path.relative_to(ROOT)}')

		return 1 if stale else 0

	for path in stale:
		path.write_text(files[path], encoding='utf-8')
		print(f'wrote {path.relative_to(ROOT)}')

	counts = ', '.join(f'{group} {len(entries(source, group))}' for group in GROUPS)
	print(f'{counts}; {len(stale)} file(s) changed')
	return 0


if __name__ == '__main__':
	sys.exit(main())
